// Deterministic contract generation. Runtime clients are generated by node-soap from these WSDLs.
const { writeFileSync } = require("node:fs");
const path = require("node:path");
const operations = {
  game: {
    NewGame: ["requestId"],
    GetGame: ["requestId", "gameId"],
    Move: ["requestId", "gameId", "expectedVersion", "direction"],
    ContinueAfterWin: ["requestId", "gameId", "expectedVersion"],
    ResetGame: ["requestId", "gameId", "expectedVersion"],
  },
  leaderboard: {
    SubmitScore: ["requestId", "gameId", "expectedVersion", "nickname"],
    GetTopScores: ["requestId", "limit"],
    GetBestScoreByNickname: ["requestId", "nickname"],
  },
};
const field = (name, type = "xsd:string", optional = false) =>
  `<xsd:element name="${name}" type="${type}"${optional ? ' minOccurs="0"' : ""}/>`;
for (const [kind, ops] of Object.entries(operations)) {
  const service = kind === "game" ? "GameService" : "LeaderboardService";
  const ns = `http://webservice.example.com/2048/${kind}/v1`;
  const complex = (name, fields) =>
    `<xsd:complexType name="${name}"><xsd:sequence>${fields}</xsd:sequence></xsd:complexType>`;
  const types =
    complex(
      "Board",
      '<xsd:element name="cell" type="xsd:long" minOccurs="16" maxOccurs="16"/>',
    ) +
    complex(
      "Game",
      field("gameId") +
        field("board", "tns:Board") +
        field("score", "xsd:long") +
        field("status") +
        field("reachedTile", "xsd:long") +
        field("version", "xsd:long") +
        field("createdAt") +
        field("updatedAt") +
        field("finishedAt", "xsd:string", true),
    ) +
    complex(
      "Entry",
      ["id", "gameId", "nickname"].map((x) => field(x)).join("") +
        field("score", "xsd:long") +
        field("reachedTile", "xsd:long") +
        field("createdAt"),
    ) +
    complex(
      "Entries",
      '<xsd:element name="entry" type="tns:Entry" minOccurs="0" maxOccurs="unbounded"/>',
    ) +
    complex(
      "Tile",
      field("row", "xsd:int") +
        field("column", "xsd:int") +
        field("value", "xsd:long"),
    );
  const response =
    field("success", "xsd:boolean") +
    field("requestId") +
    field("errorCode", "xsd:string", true) +
    field("message", "xsd:string", true) +
    field("game", "tns:Game", true) +
    field("entry", "tns:Entry", true) +
    field("entries", "tns:Entries", true) +
    field("duplicate", "xsd:boolean", true) +
    field("changed", "xsd:boolean", true) +
    field("scoreDelta", "xsd:long", true) +
    field("previousGameId", "xsd:string", true) +
    field("spawnedTile", "tns:Tile", true);
  const elements = Object.entries(ops)
    .map(
      ([op, fields]) =>
        `<xsd:element name="${op}Request"><xsd:complexType><xsd:sequence>${fields.map((x) => field(x, x === "expectedVersion" ? "xsd:long" : x === "limit" ? "xsd:int" : "xsd:string")).join("")}</xsd:sequence></xsd:complexType></xsd:element><xsd:element name="${op}Response"><xsd:complexType><xsd:sequence>${response}</xsd:sequence></xsd:complexType></xsd:element>`,
    )
    .join("");
  const messages = Object.keys(ops)
    .map(
      (op) =>
        `<message name="${op}Input"><part name="parameters" element="tns:${op}Request"/></message><message name="${op}Output"><part name="parameters" element="tns:${op}Response"/></message>`,
    )
    .join("");
  const ports = Object.keys(ops)
    .map(
      (op) =>
        `<operation name="${op}"><input message="tns:${op}Input"/><output message="tns:${op}Output"/></operation>`,
    )
    .join("");
  const bindings = Object.keys(ops)
    .map(
      (op) =>
        `<operation name="${op}"><soap:operation soapAction="${ns}/${op}"/><input><soap:body use="literal"/></input><output><soap:body use="literal"/></output></operation>`,
    )
    .join("");
  writeFileSync(
    path.join(__dirname, "../contracts", `${kind}.wsdl`),
    `<?xml version="1.0" encoding="UTF-8"?>\n<definitions xmlns="http://schemas.xmlsoap.org/wsdl/" xmlns:soap="http://schemas.xmlsoap.org/wsdl/soap/" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:tns="${ns}" targetNamespace="${ns}" name="${service}"><types><xsd:schema targetNamespace="${ns}" elementFormDefault="qualified">${types}${elements}</xsd:schema></types>${messages}<portType name="${service}PortType">${ports}</portType><binding name="${service}Binding" type="tns:${service}PortType"><soap:binding style="document" transport="http://schemas.xmlsoap.org/soap/http"/>${bindings}</binding><service name="${service}"><port name="${service}Port" binding="tns:${service}Binding"><soap:address location="http://127.0.0.1:8080/ws/${kind}"/></port></service></definitions>\n`,
  );
}
module.exports = { operations };
